import 'package:intl/intl.dart';
import '../models/models.dart';
import '../services/storage_service.dart';
import '../widgets/app_card.dart';

const defaultExercises = <List<String>>[
 ['Rosca direta','Bíceps'],['Rosca alternada','Bíceps'],['Rosca Scott','Bíceps'],['Rosca martelo','Bíceps'],
 ['Tríceps corda','Tríceps'],['Tríceps testa','Tríceps'],['Tríceps francês','Tríceps'],['Mergulho','Tríceps'],
 ['Puxada aberta','Costas'],['Puxada fechada','Costas'],['Remada baixa','Costas'],['Remada cavalinho','Costas'],['Remada unilateral','Costas'],['Pullover','Costas'],
 ['Supino reto','Peito'],['Supino inclinado','Peito'],['Crucifixo máquina','Peito'],['Crossover','Peito'],['Flexão','Peito'],
 ['Desenvolvimento','Ombros'],['Elevação lateral','Ombros'],['Elevação frontal','Ombros'],['Crucifixo inverso','Ombros'],
 ['Agachamento','Quadríceps'],['Leg press 45','Quadríceps'],['Cadeira extensora','Quadríceps'],['Afundo','Quadríceps'],
 ['Mesa flexora','Posterior'],['Cadeira flexora','Posterior'],['Stiff','Posterior'],['Terra romeno','Posterior'],
 ['Hip thrust','Glúteos'],['Elevação pélvica','Glúteos'],['Abdução','Glúteos'],['Panturrilha em pé','Panturrilhas'],['Panturrilha sentado','Panturrilhas'],
 ['Abdominal supra','Abdômen'],['Abdominal infra','Abdômen'],['Prancha','Abdômen'],['Elevação de pernas','Abdômen']
];
const muscleOrder = ['Bíceps','Tríceps','Costas','Peito','Ombros','Quadríceps','Posterior','Glúteos','Panturrilhas','Abdômen'];
const weekdays = ['Segunda','Terça','Quarta','Quinta','Sexta','Sábado','Domingo'];

class GymScreen extends StatefulWidget { const GymScreen({super.key}); @override State<GymScreen> createState()=>_GymScreenState(); }
class _GymScreenState extends State<GymScreen> {
 List<Workout> workouts=[]; List<List<String>> custom=[];
 @override void initState(){super.initState();_load();}
 Future<void> _load() async {final w=await StorageService.read('workouts');final c=await StorageService.read('exercise_library');workouts=w.map(Workout.fromJson).toList();custom=c.map((e)=>[(e['name']??'').toString(),(e['muscle']??'Outros').toString()]).toList();if(mounted)setState((){});}
 Future<void> _save()=>StorageService.write('workouts',workouts.map((e)=>e.toJson()).toList());
 List<List<String>> get library {final all=[...defaultExercises,...custom];all.sort((a,b){int x=muscleOrder.indexOf(a[1]),y=muscleOrder.indexOf(b[1]);return (x<0?99:x).compareTo(y<0?99:y);});return all;}
 Future<void> _createWorkout() async {final name=TextEditingController();final selected=<int>{DateTime.now().weekday};final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,ss)=>AlertDialog(title:const Text('Novo treino'),content:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[TextField(controller:name,autofocus:true,decoration:const InputDecoration(labelText:'Nome do treino')),const SizedBox(height:14),const Text('Dias da semana'),Wrap(spacing:5,children:List.generate(7,(i)=>FilterChip(label:Text(weekdays[i].substring(0,3)),selected:selected.contains(i+1),onSelected:(v)=>ss((){if(v)selected.add(i+1);else if(selected.length>1)selected.remove(i+1);}))) )]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Criar'))])));if(ok!=true||name.text.trim().isEmpty)return;final date=DateFormat('yyyy-MM-dd').format(DateTime.now());final created=<Workout>[];for(final d in selected){final w=Workout(id:'${DateTime.now().microsecondsSinceEpoch}-$d',name:name.text.trim(),date:date,weekday:d,exercises:[]);workouts.add(w);created.add(w);}await _save();setState((){});if(mounted)await _editWorkout(created.first);}
 Future<void> _editWorkout(Workout w)async{await showModalBottomSheet(context:context,isScrollControlled:true,builder:(_)=>WorkoutEditor(workout:w,library:library,onAddCustom:_addCustom,onChanged:(){setState((){});_save();}));await _save();}
 Future<void> _addCustom()async{final n=TextEditingController();String muscle=muscleOrder.first;final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,ss)=>AlertDialog(title:const Text('Novo exercício'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Nome')),DropdownButtonFormField<String>(initialValue:muscle,items:muscleOrder.map((m)=>DropdownMenuItem(value:m,child:Text(m))).toList(),onChanged:(v){if(v!=null)ss(()=>muscle=v);},decoration:const InputDecoration(labelText:'Grupo muscular'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Salvar'))])));if(ok==true&&n.text.trim().isNotEmpty){custom.add([n.text.trim(),muscle]);await StorageService.write('exercise_library',custom.map((e)=>{'name':e[0],'muscle':e[1]}).toList());setState((){});}}
 Future<void> _start(Workout w)async{await Navigator.push(context,MaterialPageRoute(builder:(_)=>WorkoutPlayer(workout:w,onSave:_save)));if(mounted)setState((){});}
 @override Widget build(BuildContext context){return SafeArea(child:ListView(padding:const EdgeInsets.all(16),children:[Row(children:[Expanded(child:Text('Academia',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold))),FilledButton.icon(onPressed:_createWorkout,icon:const Icon(Icons.add),label:const Text('Novo treino'))]),const SizedBox(height:12),if(workouts.isEmpty)const AppCard(child:Text('Crie seu primeiro treino para começar.')),...List.generate(7,(i){final day=workouts.where((w)=>w.weekday==i+1).toList();if(day.isEmpty)return const SizedBox.shrink();return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Padding(padding:const EdgeInsets.only(top:10,bottom:4),child:Text(weekdays[i],style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold))),...day.map((w)=>AppCard(child:ListTile(contentPadding:EdgeInsets.zero,leading:const CircleAvatar(child:Icon(Icons.fitness_center)),title:Text(w.name),subtitle:Text('${w.exercises.length} exercícios'),onTap:()=>_start(w),trailing:PopupMenuButton<String>(onSelected:(v)async{if(v=='start')await _start(w);if(v=='edit')await _editWorkout(w);if(v=='delete'){setState(()=>workouts.remove(w));await _save();}},itemBuilder:(_)=>const[PopupMenuItem(value:'start',child:Text('Iniciar treino')),PopupMenuItem(value:'edit',child:Text('Editar')),PopupMenuItem(value:'delete',child:Text('Excluir'))]))))]);})]));}
}

class WorkoutEditor extends StatefulWidget {final Workout workout;final List<List<String>> library;final VoidCallback onChanged;final VoidCallback onAddCustom;const WorkoutEditor({super.key,required this.workout,required this.library,required this.onChanged,required this.onAddCustom});@override State<WorkoutEditor> createState()=>_WorkoutEditorState();}
class _WorkoutEditorState extends State<WorkoutEditor>{String search='';
 Future<void> _add()async{String? selected;int sets=3,reps=10;final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,ss){final filtered=widget.library.where((e)=>search.isEmpty||e[0].toLowerCase().contains(search.toLowerCase())).toList();return AlertDialog(title:const Text('Adicionar exercício'),content:SizedBox(width:500,height:520,child:Column(children:[TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Buscar exercício'),onChanged:(v)=>ss(()=>search=v)),const SizedBox(height:6),Expanded(child:ListView(children:[for(final group in muscleOrder)...[Padding(padding:const EdgeInsets.only(top:8,bottom:2),child:Align(alignment:Alignment.centerLeft,child:Text(group,style:const TextStyle(fontWeight:FontWeight.bold)))),...filtered.where((e)=>e[1]==group).map((e)=>RadioListTile<String>(dense:true,value:e[0],groupValue:selected,title:Row(children:[const CircleAvatar(radius:17,child:Icon(Icons.accessibility_new,size:19)),const SizedBox(width:8),Expanded(child:Text(e[0]))]),onChanged:(v)=>ss(()=>selected=v)))] ])),Row(children:[Expanded(child:DropdownButtonFormField<int>(initialValue:sets,items:[2,3,4,5].map((x)=>DropdownMenuItem(value:x,child:Text('$x séries'))).toList(),onChanged:(v){if(v!=null)ss(()=>sets=v);},decoration:const InputDecoration(labelText:'Séries'))),const SizedBox(width:8),Expanded(child:DropdownButtonFormField<int>(initialValue:reps,items:[5,6,8,10,12,15,20].map((x)=>DropdownMenuItem(value:x,child:Text('$x reps'))).toList(),onChanged:(v){if(v!=null)ss(()=>reps=v);},decoration:const InputDecoration(labelText:'Repetições')))]])),actions:[TextButton(onPressed:widget.onAddCustom,child:const Text('Novo exercício')),TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancelar')),FilledButton(onPressed:selected==null?null:()=>Navigator.pop(c,true),child:const Text('Adicionar'))]}));if(ok==true&&selected!=null){final e=widget.library.firstWhere((x)=>x[0]==selected);setState(()=>widget.workout.exercises.add(Exercise(id:DateTime.now().microsecondsSinceEpoch.toString(),name:e[0],muscle:e[1],sets:sets,reps:reps)));widget.onChanged();}}
 @override Widget build(BuildContext context)=>SafeArea(child:SizedBox(height:MediaQuery.sizeOf(context).height*.88,child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[Row(children:[Expanded(child:Text('Editar: ${widget.workout.name}',style:Theme.of(context).textTheme.titleLarge)),IconButton(onPressed:()=>Navigator.pop(context),icon:const Icon(Icons.close))]),Expanded(child:ReorderableListView.builder(itemCount:widget.workout.exercises.length,onReorder:(a,b){setState((){if(b>a)b--;final x=widget.workout.exercises.removeAt(a);widget.workout.exercises.insert(b,x);});widget.onChanged();},itemBuilder:(c,i){final e=widget.workout.exercises[i];return ListTile(key:ValueKey(e.id),leading:const CircleAvatar(child:Icon(Icons.accessibility_new)),title:Text(e.name),subtitle:Text('${e.muscle} • ${e.sets} séries × ${e.reps}'),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:(){setState(()=>widget.workout.exercises.removeAt(i));widget.onChanged();}));})),FilledButton.icon(onPressed:_add,icon:const Icon(Icons.add),label:const Text('Adicionar exercício'))]))));}
}

class WorkoutPlayer extends StatefulWidget{final Workout workout;final Future<void> Function() onSave;const WorkoutPlayer({super.key,required this.workout,required this.onSave});@override State<WorkoutPlayer> createState()=>_WorkoutPlayerState();}
class _WorkoutPlayerState extends State<WorkoutPlayer>{@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.workout.name)),body:ListView(padding:const EdgeInsets.all(16),children:[...widget.workout.exercises.map((e)=>AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[const CircleAvatar(child:Icon(Icons.accessibility_new)),const SizedBox(width:10),Expanded(child:Text(e.name,style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)))]),Text('${e.muscle} • ${e.sets} séries × ${e.reps} repetições'),...List.generate(e.sets,(i)=>Row(children:[Text('Série ${i+1}'),const SizedBox(width:8),Expanded(child:TextFormField(initialValue:e.weights[i]==0?'':e.weights[i].toString(),keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'kg'),onChanged:(v)=>e.weights[i]=double.tryParse(v.replaceAll(',','.'))??0)),Checkbox(value:e.done[i],onChanged:(v)=>setState(()=>e.done[i]=v??false))]))]))),FilledButton(onPressed:()async{await widget.onSave();if(mounted)Navigator.pop(c);},child:const Text('Salvar treino'))]));}
